import os
import numpy as np
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader, Dataset
from datasets import load_dataset

# Create working directory
working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

# Device configuration
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

# Load datasets from Hugging Face
datasets = {
    "dataset_1": load_dataset("imdb", split="train[:1000]"),  # small portion of IMDB
    "dataset_2": load_dataset(
        "ag_news", split="train[:1000]"
    ),  # small portion of AG News
    "dataset_3": load_dataset(
        "yelp_polarity", split="train[:1000]"
    ),  # small portion of Yelp
}


class ReviewDataset(Dataset):
    def __init__(self, dataset):
        self.data = dataset["text"]  # Assuming text reviews are in 'text' column
        self.labels = dataset["label"]  # Assuming labels are in 'label' column

    def __len__(self):
        return len(self.labels)

    def __getitem__(self, idx):
        return {
            "features": torch.tensor(self.data[idx]),  # Should ideally be tokenized
            "label": torch.tensor(self.labels[idx], dtype=torch.float).to(device),
        }


# Model definition with customizable activation function
class RQIModel(nn.Module):
    def __init__(self, activation_fn):
        super(RQIModel, self).__init__()
        self.fc1 = nn.Linear(5, 10)
        self.fc2 = nn.Linear(10, 1)
        self.activation_fn = activation_fn

    def forward(self, x):
        x = self.activation_fn(self.fc1(x))
        x = self.fc2(x)
        return x


# Experiment data storage
experiment_data = {
    "activation_function_tuning": {
        "ReLU": {
            "metrics": {"train": [], "val": []},
            "losses": {"train": [], "val": []},
            "predictions": [],
            "ground_truth": [],
        },
        "LeakyReLU": {
            "metrics": {"train": [], "val": []},
            "losses": {"train": [], "val": []},
            "predictions": [],
            "ground_truth": [],
        },
        "ELU": {
            "metrics": {"train": [], "val": []},
            "losses": {"train": [], "val": []},
            "predictions": [],
            "ground_truth": [],
        },
        "Tanh": {
            "metrics": {"train": [], "val": []},
            "losses": {"train": [], "val": []},
            "predictions": [],
            "ground_truth": [],
        },
    }
}

activation_functions = {
    "ReLU": nn.ReLU(),
    "LeakyReLU": nn.LeakyReLU(0.01),
    "ELU": nn.ELU(),
    "Tanh": nn.Tanh(),
}

# Prepare dataset
for key, dataset in datasets.items():
    dataset_instance = ReviewDataset(dataset)
    train_size = int(0.8 * len(dataset_instance))
    val_size = len(dataset_instance) - train_size
    train_data, val_data = torch.utils.data.random_split(
        dataset_instance, [train_size, val_size]
    )
    train_loader = DataLoader(train_data, batch_size=32, shuffle=True)
    val_loader = DataLoader(val_data, batch_size=32, shuffle=False)

    # Training loop for different activation functions
    for act_name, act_func in activation_functions.items():
        print(f"Training with activation function: {act_name} on {key}")
        model = RQIModel(act_func).to(device)
        criterion = nn.MSELoss()
        optimizer = optim.Adam(model.parameters(), lr=0.001)
        reviewer_impact_score = 0

        for epoch in range(100):
            model.train()
            train_loss = 0.0
            for batch in train_loader:
                batch = {
                    k: v.to(device)
                    for k, v in batch.items()
                    if isinstance(v, torch.Tensor)
                }
                features = batch["features"]  # Note: Should be tokenized
                labels = batch["label"]
                optimizer.zero_grad()
                outputs = model(features).squeeze()
                loss = criterion(outputs, labels)
                loss.backward()
                optimizer.step()
                train_loss += loss.item()

            train_loss /= len(train_loader)
            experiment_data["activation_function_tuning"][act_name]["losses"][
                "train"
            ].append(train_loss)
            print(f"Epoch {epoch}: training_loss = {train_loss:.4f}")

            # Validation loop
            model.eval()
            val_loss = 0.0
            with torch.no_grad():
                for batch in val_loader:
                    batch = {
                        k: v.to(device)
                        for k, v in batch.items()
                        if isinstance(v, torch.Tensor)
                    }
                    features = batch["features"]  # Note: Should be tokenized
                    labels = batch["label"]
                    outputs = model(features).squeeze()
                    loss = criterion(outputs, labels)
                    val_loss += loss.item()

            val_loss /= len(val_loader)
            experiment_data["activation_function_tuning"][act_name]["losses"][
                "val"
            ].append(val_loss)
            print(f"Epoch {epoch}: validation_loss = {val_loss:.4f}")

# Save experiment data
np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)

