        self.data = dataset["text"]
        self.labels = dataset["label"]

    def __len__(self):
        return len(self.labels)

    def __getitem__(self, idx):
        # Tokenize the input texts
        inputs = tokenizer(
            self.data[idx],
            return_tensors="pt",
            padding=True,
            truncation=True,
            max_length=512,
        )
        return {
            "features": inputs["input_ids"].squeeze(
                0
            ),  # Squeeze to get rid of singleton dimensions
            "label": torch.tensor(self.labels[idx], dtype=torch.float).to(device),
